def transform(grid):
    h,w=len(grid),len(grid[0])
    ones=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    sixes=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==6]
    out=[row[:] for row in grid]
    # connect every pair of 1s on 45-degree diagonal
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            if abs(r2-r1)==abs(c2-c1):
                dr=1 if r2>r1 else -1
                dc=1 if c2>c1 else -1
                r,c=r1+dr,c1+dc
                while (r,c)!=(r2,c2):
                    if out[r][c]==4: out[r][c]=1
                    r+=dr;c+=dc
    # Any 6 lying on a diagonal 1 connector makes perpendicular 6 line across grid.
    # likely diagonal is the line of 1 segment; perpendicular complete in opposite orientation.
    for r,c in sixes:
        if any((r-r1)==(c-c1) or (r-r1)==-(c-c1) for r1,c1 in ones):
            # Given diagonal slope +1, perpendicular slope -1; vice versa slope +1
            # Identify direction of 1 line through marker; infer from pairs
            for i,(r1,c1) in enumerate(ones):
                for r2,c2 in ones[i+1:]:
                    if abs(r2-r1)==abs(c2-c1) and (r-r1)*(c2-c1)==(c-c1)*(r2-r1) and (r-r1)*(r2-r1)>=0:
                        # line through six has same slope as connector
                        if (r2-r1)==(c2-c1):
                            for rr in range(h):
                                cc=c+(rr-r)
                                if 0<=cc<w and out[rr][cc]==4: out[rr][cc]=6
                        else:
                            for rr in range(h):
                                cc=c-(rr-r)
                                if 0<=cc<w and out[rr][cc]==4: out[rr][cc]=6
    return out

