def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]
    for c in range(w):
        cells = [grid[r][c] for r in range(h) if grid[r][c] != background]
        for r, value in enumerate(cells, start=h - len(cells)):
            out[r][c] = value
    return out

def transform(grid):
    """Translate the non-background pattern two cells to the right."""
