    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg and c + 2 < w:
                out[r][c + 2] = value
    return out

def transform(grid):
    """Extend each left-anchored horizontal colored stripe to the right in color 1."""
    out = [row[:] for row in grid]
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        # These stripe rows begin at the left edge; fill only the background suffix
        # immediately after the stripe, leaving fully extended rows unchanged.
        if row[0] != background:
            end = 0
            while end < len(row) and row[end] != background:
                end += 1
            if end < len(row):
                out[r][end:] = [1] * (len(row) - end)
    return out

