def transform(grid):
    """Mark missing foreground cells in the trailing blank suffix of a repeated row-block."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find separated non-background row blocks.
    groups = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        a = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        groups.append((a, r))
    best = []
    best_score = 0
    for i, (a, b) in enumerate(groups):
        for c, d in groups[i+1:]:
            if b-a != d-c:
                continue
            for src, dst in (((a,b),(c,d)), ((c,d),(a,b))):
                marks = []
                for sr, tr in zip(range(*src), range(*dst)):
                    row = grid[tr]
                    # Only inspect the final contiguous background suffix.
                    end = w
                    while end > 0 and row[end-1] == bg:
                        end -= 1
                    if end == w:
                        continue
                    for col in range(end, w):
                        if grid[sr][col] != bg:
                            marks.append((tr, col))
                if len(marks) > best_score:
                    best_score, best = len(marks), marks
    out = [row[:] for row in grid]
    for rr, cc in best:
        out[rr][cc] = 1
    return out

