from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            top, left = min(y for y,x in cells), min(x for y,x in cells)
            bottom, right = max(y for y,x in cells), max(x for y,x in cells)
            objects.append((left, top, color, cells, bottom-top+1, right-left+1))
    objects.sort(key=lambda o: o[0])
    out = [[0]*w for _ in range(h)]
    for i, (_, _, color, cells, oh, ow) in enumerate(objects):
        for y, x in cells:
            ny = i + (oh - 1 - (y - min(yy for yy,xx in cells)))
            nx = i + (ow - 1 - (x - min(xx for yy,xx in cells)))
            if 0 <= ny < h and 0 <= nx < w:
                out[ny][nx] = color
    return out

