def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Fill internal holes in horizontal bars and project the hole's color upward.
    rays = []
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v]
        # Horizontal bars are dense; ignore sparse lower marker strokes.
        if len(nz) < 5:
            continue
        for c in range(nz[0] + 1, nz[-1]):
            if row[c] == 0:
                left = next((row[k] for k in range(c - 1, -1, -1) if row[k]), 0)
                right = next((row[k] for k in range(c + 1, w) if row[k]), 0)
                if left and right and left != right:
                    out[r][c] = right
                else:
                    out[r][c] = left or right
