        # Parallel horizontal boundary segments at distinct columns; project each
        # marker through the horizontal displacement and connect their rows.
        top, bottom = min(rail_rows), max(rail_rows)
        top_cols = [c for c,v in enumerate(grid[top]) if v == rail]
        bot_cols = [c for c,v in enumerate(grid[bottom]) if v == rail]
        delta = (sum(bot_cols)//len(bot_cols)) - (sum(top_cols)//len(top_cols))
        for r in range(top+1,bottom):
            for c in range(w):
                if grid[r][c] == marker:
                    target = c + delta
                    if 0 <= target < w:
                        for rr in range(top+1,bottom+1):
                            if out[rr][target] == bg:
                                out[rr][target] = marker
                        out[r][c] = 4
    elif rail_cols:
        # Offset vertical boundary segments: markers travel toward the active
        # rail in their lane, while their translated row is filled across lane.
        left, right = min(rail_cols), max(rail_cols)
        left_rows = [r for r in range(h) if grid[r][left] == rail]
        right_rows = [r for r in range(h) if grid[r][right] == rail]
        # Rows in the first boundary's lane and corresponding rows in second lane.
        d = (sum(right_rows)//len(right_rows)) - (sum(left_rows)//len(left_rows))
        for r in range(h):
            for c in range(w):
                if grid[r][c] != marker:
